#chat .mes .mes_text b, #chat .mes .mes_text strong { color: #1661ab !important; }

#chat .mes .mes_text { text-align: justify !important; }

#chat .mes .mes_text em, #chat .mes .mes_text i { border: 1px dashed currentColor; border-radius: 3px; padding: 0 3px; font-style: italic; }

#chat .mes .mes_text q { text-decoration: underline dashed currentColor 0.5px; text-underline-offset: 3px; }

/* 用户名字体 */
#chat .mes[is_user="true"] .name_text { font-family: ChillHuoSong_F !important; }

/* 角色名字体 */
#chat .mes:not([is_user="true"]) .name_text { font-family: ChillHuoSong_F !important; }

/* 名字字体大小 */
#chat .mes .name_text { font-size: 22px !important; }

/* 名字特效 */
body #chat .mes .name_text { text-shadow: 0.20px 0.00px 0 #000000, 0.18px 0.08px 0 #000000, 0.14px 0.14px 0 #000000, 0.08px 0.18px 0 #000000, 0.00px 0.20px 0 #000000, -0.08px 0.18px 0 #000000, -0.14px 0.14px 0 #000000, -0.18px 0.08px 0 #000000, -0.20px 0.00px 0 #000000, -0.18px -0.08px 0 #000000, -0.14px -0.14px 0 #000000, -0.08px -0.18px 0 #000000, -0.00px -0.20px 0 #000000, 0.08px -0.18px 0 #000000, 0.14px -0.14px 0 #000000, 0.18px -0.08px 0 #000000 !important; }

/* 头像顶部居中 */
#chat .mes { display: flex !important; flex-direction: column !important; align-items: center !important; }
#chat .mes .mesAvatarWrapper { display: flex !important; flex-direction: column !important; align-items: center !important; width: auto !important; margin: 0 auto !important; padding: 0 !important; transform: translate(71px, 25px) !important; }
