#chat .mes .avatar {
  width: 80px !important; height: 80px !important;
  min-width: 80px !important; min-height: 80px !important;
  max-width: 80px !important; max-height: 80px !important;
  border-radius: 8px !important; overflow: hidden !important;
}
#chat .mes .avatar img {
  width: 100% !important; height: 100% !important;
  object-fit: cover !important; border-radius: 8px !important;
}

/* 头像框 */
#chat .mes .avatar { position: relative !important; overflow: visible !important; }
#chat .mes .avatar::before {
  content: ""; position: absolute; top: 50%; left: 50%;
  transform: translate(-50%, -50%); z-index: 9; pointer-events: none;
